# __add__
m1 = mne.channels.make_dig_montage(ch_pos={'A': [0.0, 0.1, 0.0], 'B': [0.1, 0.0, 0.0]}, nasion=[0.0, 0.1, 0.0], lpa=[-0.1, 0.0, 0.0], rpa=[0.1, 0.0, 0.0])
