# 1020 selections
NAMES = ['Fp1', 'Fp2', 'F7', 'F3', 'Fz', 'F4', 'F8', 'T7', 'C3', 'Cz', 'C4', 'T8',
         'P7', 'P3', 'Pz', 'P4', 'P8', 'O1', 'O2']
info = mne.create_info(NAMES, 100., 'eeg')
sel = mne.channels.make_1020_channel_selections(info, return_ch_names=True)
checks("sel_left", sel['Left'])
checks("sel_mid", sel['Midline'])
checks("sel_right", sel['Right'])
raw = mne.io.RawArray(mk(19, 400, 0.2) * 1e-5, info)
raw.set_montage('standard_1020')
sel2 = mne.channels.make_1020_channel_selections(raw.info, return_ch_names=True)
checks("sel2_left", sel2['Left'])
checks("sel2_mid", sel2['Midline'])
checks("sel2_right", sel2['Right'])

# combine_channels
rc = mne.channels.combine_channels(raw, {'frontal': [0, 1, 4], 'occ': [17, 18]})
checks("cc_names", rc.ch_names)
check("cc_data", rc.get_data()[:, 10:13], 1e-9, 1e-15)
rc2 = mne.channels.combine_channels(raw, {'a': [0, 1, 4], 'b': [5, 6, 7, 8]}, method='median')
check("cc_med", rc2.get_data()[:, 10:13], 1e-9, 1e-15)
rc3 = mne.channels.combine_channels(raw, {'a': [0, 1, 4]}, method='std')
check("cc_std", rc3.get_data()[:, 10:13], 1e-9, 1e-15)
ev = np.array([[50, 0, 1], [150, 0, 1], [250, 0, 2]])
ep = mne.Epochs(raw, ev, tmin=-0.1, tmax=0.4, baseline=None, preload=True)
ce = mne.channels.combine_channels(ep, {'frontal': [0, 1, 4]})
check("cc_ep", ce.get_data()[1, :, 5:8], 1e-9, 1e-15)
cv = mne.channels.combine_channels(ep.average(), {'frontal': [0, 1, 4]})
check("cc_evk", cv.data[:, 5:8], 1e-9, 1e-15)

# transforms
from mne.transforms import apply_trans, rotation, translation, scaling, rotation3d, rotation_angles, _cart_to_sph, _sph_to_cart
T = np.dot(translation(0.1, -0.2, 0.3), rotation(0.3, -0.2, 0.5))
pts = np.array([[1.0, 2.0, 3.0], [-0.5, 0.25, 0.1]])
check("tr_apply", apply_trans(T, pts), 1e-9, 1e-12)
check("tr_nomove", apply_trans(T, pts, move=False), 1e-9, 1e-12)
check("tr_scale", np.dot(scaling(2.0, 3.0, 4.0), T), 1e-9, 1e-12)
check("tr_angles", rotation_angles(rotation3d(0.3, -0.2, 0.5)), 1e-9, 1e-12)
check("tr_sph", _cart_to_sph(pts), 1e-9, 1e-12)
check("tr_cart", _sph_to_cart(_cart_to_sph(pts)), 1e-9, 1e-12)
